"""Deterministic reason templates, in English and Spanish (never generated by an LLM).

A ``Reason`` is a code plus language-neutral parameters; ``text`` renders it. The English text is
what goes into ``IndicatorStatus.reason``; the app renders the Spanish one from the same code.
"""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass, field
from enum import StrEnum

from crew_self_check.core.contract import Environment


class Language(StrEnum):
    EN = "en"
    ES = "es"


class ReasonCode(StrEnum):
    NO_DATA = "no_data"
    BUILDING_BASELINE = "building_baseline"
    WAITING_TRANSITION = "waiting_transition"
    STALE_READING = "stale_reading"
    PERSONAL_OK = "personal_ok"
    PERSONAL_ABOVE = "personal_above"
    PERSONAL_BELOW = "personal_below"
    TRANSITION_OK = "transition_ok"
    TRANSITION_ABOVE = "transition_above"
    TRANSITION_BELOW = "transition_below"
    POPULATION_OK = "population_ok"
    POPULATION_WATCH_HIGH = "population_watch_high"
    POPULATION_WATCH_LOW = "population_watch_low"
    POPULATION_ACT_HIGH = "population_act_high"
    POPULATION_ACT_LOW = "population_act_low"


_EN, _ES = Language.EN, Language.ES

_POPULATION_EN = "the typical population range for your age and sex (population reference, not your personal baseline)."  # noqa: E501
_POPULATION_ES = "rango típico de la población para tu edad y sexo (referencia poblacional, no tu línea base personal)."  # noqa: E501

TEMPLATES: dict[ReasonCode, dict[Language, str]] = {
    ReasonCode.NO_DATA: {
        _EN: "No readings yet in this environment.",
        _ES: "Aún no hay lecturas en este espacio.",
    },
    ReasonCode.BUILDING_BASELINE: {
        _EN: "Building your personal baseline: {days} of {needed} days.",
        _ES: "Construyendo tu línea base personal: {days} de {needed} días.",
    },
    ReasonCode.WAITING_TRANSITION: {
        _EN: "Waiting for {needed} readings to compare with your previous baseline ({previous}); "
        "{have} so far.",
        _ES: "Esperando {needed} lecturas para comparar con tu línea base anterior ({previous}); "
        "hay {have}.",
    },
    ReasonCode.STALE_READING: {
        _EN: "No recent reading: the latest is {days} days old.",
        _ES: "Sin lectura reciente: la última tiene {days} días.",
    },
    ReasonCode.PERSONAL_OK: {
        _EN: "Within your personal range.",
        _ES: "Dentro de tu rango personal.",
    },
    ReasonCode.PERSONAL_ABOVE: {
        _EN: "{n} consecutive readings above personal range",
        _ES: "{n} lecturas seguidas por encima de tu rango personal",
    },
    ReasonCode.PERSONAL_BELOW: {
        _EN: "{n} consecutive readings below personal range",
        _ES: "{n} lecturas seguidas por debajo de tu rango personal",
    },
    ReasonCode.TRANSITION_OK: {
        _EN: "Within your previous baseline ({previous}); "
        "your own baseline here is still building.",
        _ES: "Dentro de tu línea base anterior ({previous}); la de este espacio aún se construye.",
    },
    ReasonCode.TRANSITION_ABOVE: {
        _EN: "{n} consecutive readings above your previous baseline ({previous}); "
        "your own baseline here is still building.",
        _ES: "{n} lecturas seguidas por encima de tu línea base anterior ({previous}); "
        "la de este espacio aún se construye.",
    },
    ReasonCode.TRANSITION_BELOW: {
        _EN: "{n} consecutive readings below your previous baseline ({previous}); "
        "your own baseline here is still building.",
        _ES: "{n} lecturas seguidas por debajo de tu línea base anterior ({previous}); "
        "la de este espacio aún se construye.",
    },
    ReasonCode.POPULATION_OK: {
        _EN: "Within " + _POPULATION_EN,
        _ES: "Dentro del " + _POPULATION_ES,
    },
    ReasonCode.POPULATION_WATCH_HIGH: {
        _EN: "Above " + _POPULATION_EN,
        _ES: "Por encima del " + _POPULATION_ES,
    },
    ReasonCode.POPULATION_WATCH_LOW: {
        _EN: "Below " + _POPULATION_EN,
        _ES: "Por debajo del " + _POPULATION_ES,
    },
    ReasonCode.POPULATION_ACT_HIGH: {
        _EN: "Far above " + _POPULATION_EN,
        _ES: "Muy por encima del " + _POPULATION_ES,
    },
    ReasonCode.POPULATION_ACT_LOW: {
        _EN: "Far below " + _POPULATION_EN,
        _ES: "Muy por debajo del " + _POPULATION_ES,
    },
}

_ENVIRONMENT_NAMES: dict[Language, dict[Environment, str]] = {
    _EN: {
        Environment.EARTH: "Earth",
        Environment.SPACECRAFT: "spacecraft",
        Environment.PLANET: "planet",
    },
    _ES: {
        Environment.EARTH: "Tierra",
        Environment.SPACECRAFT: "nave",
        Environment.PLANET: "planeta",
    },
}


@dataclass(frozen=True, slots=True)
class Reason:
    code: ReasonCode
    params: Mapping[str, object] = field(default_factory=dict)

    def text(self, language: Language) -> str:
        """Render in ``language``; a missing parameter raises ``KeyError`` instead of a blank."""
        values = {
            key: _ENVIRONMENT_NAMES[language][value] if isinstance(value, Environment) else value
            for key, value in self.params.items()
        }
        return TEMPLATES[self.code][language].format(**values)
